done = 0
for lang, figs in L.items():
    for key, (intro, alt, cap) in figs.items():
        paper, name, n, head = POS[key]
        path = f'{T}{lang}/{paper}.md'
        try: s = open(path).read()
        except FileNotFoundError: continue
        if len(s.splitlines()) < 50 or f'/figures/{paper}/{name}.svg' in s: continue
        m = re.search(r'^' + re.escape(head), s, re.M); assert m, (lang, key)
        i = m.start()
        while True:  # step above anchor-alias divs that belong to the heading
            pre = s[:i].rstrip('\n'); last = pre.rsplit('\n', 1)[-1]
            if last.startswith('<div id=') and 'anchor-alias' in last: i = len(pre) - len(last)
            else: break
        u = f'/figures/{paper}/{name}.png'
        block = f'{intro}\n\n![{alt}](/figures/{paper}/{name}.svg)\n\n*{FIGW[lang].format(n=n)} {cap} {PNG[lang].format(u=u)}*\n\n'
        s = s[:i] + block + s[i:]; open(path, 'w').write(s); done += 1
print('inserted', done)
